/* ===================== BÀI 1 · Khí cụ điện là gì? Vai trò trong máy tự động và hệ thống nhà xưởng ===================== */
/* Bài 1 · Khí cụ điện là gì? Vai trò trong máy tự động và hệ thống nhà xưởng (E00.01) — sinh bởi tools/author/kcd/k01.py, không sửa tay.
   Phòng mô phỏng từng bước và bài tập chấm tự động; phần chữ bài học ở lesson.html (nội dung bảo vệ). */
makeMtLab(document.getElementById("lab-l1"),{id:"l1",scenarios:[{"label": "Ví dụ: Nguồn, dây, khí cụ, tải trong mạch đèn", "note": "Gọi tên bốn thành phần của một mạch; khí cụ điện là phần quyết định và bảo vệ.", "steps": [{"t": "Một mạch đèn chiếu sáng 24 V", "html": "<div class=\"mt-flow\"><div class=\"mt-box\"><b>Bộ nguồn 24 VDC<\/b><small>nguồn<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>Dây dẫn<\/b><small>đường dẫn<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>F0 cầu chì<\/b><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>S1 công tắc<\/b><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>H1 đèn chiếu sáng<\/b><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>Dây về 0 V<\/b><small>đường dẫn<\/small><\/div><\/div>", "say": "<p>Mạch nhỏ nhất vẫn có bốn thành phần: nguồn, đường dẫn, khí cụ điện và tải. Bấm <b>Bước tiếp<\/b> để gọi tên từng thứ.<\/p>"}, {"t": "Nguồn: nơi cấp năng lượng", "html": "<div class=\"mt-flow\"><div class=\"mt-box on\"><b>Bộ nguồn 24 VDC<\/b><small>nguồn<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>Dây dẫn<\/b><small>đường dẫn<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>F0 cầu chì<\/b><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>S1 công tắc<\/b><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>H1 đèn chiếu sáng<\/b><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>Dây về 0 V<\/b><small>đường dẫn<\/small><\/div><\/div>", "say": "<p>Bộ nguồn biến điện lưới thành 24 V một chiều. Trong nhà xưởng, nguồn có thể là máy biến áp, lưới hạ áp hoặc bộ nguồn như ở đây.<\/p>"}, {"t": "F0: khí cụ bảo vệ", "html": "<div class=\"mt-flow\"><div class=\"mt-box\"><b>Bộ nguồn 24 VDC<\/b><small>nguồn<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>Dây dẫn<\/b><small>đường dẫn<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>F0 cầu chì<\/b><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>S1 công tắc<\/b><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>H1 đèn chiếu sáng<\/b><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>Dây về 0 V<\/b><small>đường dẫn<\/small><\/div><\/div>", "say": "<p>Cầu chì tự cắt mạch khi dòng quá lớn (ví dụ dây bị chập). Nó không cấp năng lượng, không dùng năng lượng để làm việc có ích: nó <b>bảo vệ<\/b>.<\/p>"}, {"t": "S1: khí cụ đóng cắt, thao tác", "html": "<div class=\"mt-flow\"><div class=\"mt-box\"><b>Bộ nguồn 24 VDC<\/b><small>nguồn<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>Dây dẫn<\/b><small>đường dẫn<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>F0 cầu chì<\/b><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>S1 công tắc<\/b><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>H1 đèn chiếu sáng<\/b><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>Dây về 0 V<\/b><small>đường dẫn<\/small><\/div><\/div>", "say": "<p>Công tắc do người bật, tắt: vừa là thiết bị thao tác, vừa đóng cắt dòng của đèn.<\/p>"}, {"t": "H1: tải", "html": "<div class=\"mt-flow\"><div class=\"mt-box\"><b>Bộ nguồn 24 VDC<\/b><small>nguồn<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>Dây dẫn<\/b><small>đường dẫn<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>F0 cầu chì<\/b><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>S1 công tắc<\/b><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box done\"><b>H1 đèn chiếu sáng<\/b><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>Dây về 0 V<\/b><small>đường dẫn<\/small><\/div><\/div>", "ask": {"q": "Trong mạch này, đèn chiếu sáng H1 là gì?", "o": ["Khí cụ bảo vệ", "Tải: nơi năng lượng được dùng", "Nguồn"], "a": 1}, "say": "<p>Đèn biến điện năng thành ánh sáng: đó là <b>tải<\/b>. Nếu bỏ hết khí cụ, mạch vẫn sáng, nhưng không tắt được và không được bảo vệ.<\/p>"}, {"t": "Bảng phân loại", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Thành phần<\/th><th scope=\"col\">Trong mạch này<\/th><\/tr><\/thead><tbody><tr><td>Nguồn<\/td><td>Bộ nguồn 24 VDC<\/td><\/tr><tr><td>Đường dẫn<\/td><td>Dây dẫn<\/td><\/tr><tr><td>Khí cụ điện<\/td><td class=\"hi\">F0 (bảo vệ), S1 (đóng cắt, thao tác)<\/td><\/tr><tr><td>Tải<\/td><td>H1<\/td><\/tr><\/tbody><\/table>", "say": "<p>Khí cụ điện là phần nằm giữa nguồn và tải để <b>quyết định và bảo vệ<\/b> đường đi của năng lượng.<\/p>"}]}, {"label": "Ví dụ: Đường năng lượng tới động cơ băng tải", "note": "Mạch động lực: Q1, KM1, F1 làm ba việc khác nhau trước khi năng lượng tới M1.", "steps": [{"t": "Máy băng tải: mạch động lực", "html": "<div class=\"mt-flow\"><div class=\"mt-box\"><b>L1 L2 L3<\/b><small>nguồn 3 pha<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>Q1<\/b><small>CB động lực<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>KM1<\/b><small>tiếp điểm chính<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>F1<\/b><small>phần tử nhiệt<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>M1<\/b><small>động cơ<\/small><\/div><\/div>", "say": "<p>Năng lượng đi từ nguồn 3 pha qua ba khí cụ rồi mới tới động cơ M1.<\/p>"}, {"t": "Q1: đóng cắt bằng tay và bảo vệ ngắn mạch", "html": "<div class=\"mt-flow\"><div class=\"mt-box\"><b>L1 L2 L3<\/b><small>nguồn 3 pha<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>Q1<\/b><small>CB động lực<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>KM1<\/b><small>tiếp điểm chính<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>F1<\/b><small>phần tử nhiệt<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>M1<\/b><small>động cơ<\/small><\/div><\/div>", "say": "<p>Q1 là CB động lực: người vận hành đóng, cắt bằng tay; khi ngắn mạch, Q1 tự cắt.<\/p>"}, {"t": "KM1: đóng cắt theo lệnh", "html": "<div class=\"mt-flow\"><div class=\"mt-box\"><b>L1 L2 L3<\/b><small>nguồn 3 pha<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>Q1<\/b><small>CB động lực<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>KM1<\/b><small>tiếp điểm chính<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>F1<\/b><small>phần tử nhiệt<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>M1<\/b><small>động cơ<\/small><\/div><\/div>", "ask": {"q": "Ai ra lệnh cho tiếp điểm chính KM1 đóng?", "o": ["Dòng điện của động cơ", "Relay nhiệt F1", "Cuộn hút KM1, do mạch điều khiển cấp điện"], "a": 2}, "say": "<p>Tiếp điểm chính của contactor KM1 đóng khi cuộn hút của nó có điện. Cuộn hút nằm ở mạch điều khiển (ví dụ kế tiếp).<\/p>"}, {"t": "F1: bảo vệ quá tải động cơ", "html": "<div class=\"mt-flow\"><div class=\"mt-box\"><b>L1 L2 L3<\/b><small>nguồn 3 pha<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>Q1<\/b><small>CB động lực<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>KM1<\/b><small>tiếp điểm chính<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>F1<\/b><small>phần tử nhiệt<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>M1<\/b><small>động cơ<\/small><\/div><\/div>", "say": "<p>Dòng động cơ đi qua phần tử nhiệt của F1. Quá tải kéo dài thì F1 tác động, mở tiếp điểm 95-96 trong mạch điều khiển để KM1 nhả.<\/p>"}, {"t": "M1 quay: năng lượng tới tải", "html": "<div class=\"mt-flow\"><div class=\"mt-box\"><b>L1 L2 L3<\/b><small>nguồn 3 pha<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>Q1<\/b><small>CB động lực<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>KM1<\/b><small>tiếp điểm chính<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>F1<\/b><small>phần tử nhiệt<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>M1<\/b><small>động cơ<\/small><\/div><\/div><table class=\"mt-tab\"><thead><tr><th scope=\"col\">Thiết bị<\/th><th scope=\"col\">Nhóm chức năng<\/th><\/tr><\/thead><tbody><tr><td>Q1<\/td><td>đóng cắt + bảo vệ ngắn mạch<\/td><\/tr><tr><td>KM1<\/td><td>đóng cắt theo lệnh<\/td><\/tr><tr><td>F1<\/td><td>bảo vệ quá tải<\/td><\/tr><tr><td>M1<\/td><td>tải<\/td><\/tr><\/tbody><\/table>", "say": "<p>Ba khí cụ, ba việc khác nhau. Không thiết bị nào làm thay được việc của thiết bị kia.<\/p>"}]}, {"label": "Ví dụ: Lệnh Start đi qua mạch điều khiển", "note": "Đường dòng tới cuộn KM1, tự giữ bằng tiếp điểm 13-14, Stop cắt đường dòng.", "steps": [{"t": "Lúc nghỉ", "html": "<div class=\"mt-flow\"><div class=\"mt-box\"><b>+24 V<\/b><small>nguồn điều khiển<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>F0<\/b><small>cầu chì<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>F1 95-96<\/b><small>NC của relay nhiệt<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>S0<\/b><small>dừng khẩn, NC<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>S1<\/b><small>Stop, NC<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>S2 ∥ KM1 13-14<\/b><small>Start NO ∥ tự giữ<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>KM1 A1-A2<\/b><small>cuộn hút<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>0 V<\/b><\/div><\/div><table class=\"mt-tab\"><thead><tr><th scope=\"col\">Thiết bị<\/th><th scope=\"col\">Trạng thái<\/th><\/tr><\/thead><tbody><tr><td>S2 Start<\/td><td>nhả<\/td><\/tr><tr><td>Cuộn KM1<\/td><td class=\"dim\">nhả<\/td><\/tr><tr><td>Động cơ M1<\/td><td class=\"dim\">đứng yên<\/td><\/tr><tr><td>Đèn chạy H1<\/td><td>tắt<\/td><\/tr><\/tbody><\/table>", "say": "<p>F1 95-96, S0, S1 là tiếp điểm thường đóng nên đang dẫn điện; S2 và KM1 13-14 thường mở nên đang hở. Cuộn KM1 chưa có điện.<\/p>"}, {"t": "Nhấn S2: cuộn KM1 có điện", "html": "<div class=\"mt-flow\"><div class=\"mt-box\"><b>+24 V<\/b><small>nguồn điều khiển<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>F0<\/b><small>cầu chì<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>F1 95-96<\/b><small>NC của relay nhiệt<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>S0<\/b><small>dừng khẩn, NC<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>S1<\/b><small>Stop, NC<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>S2 ∥ KM1 13-14<\/b><small>Start NO ∥ tự giữ<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>KM1 A1-A2<\/b><small>cuộn hút<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>0 V<\/b><\/div><\/div><table class=\"mt-tab\"><thead><tr><th scope=\"col\">Thiết bị<\/th><th scope=\"col\">Trạng thái<\/th><\/tr><\/thead><tbody><tr><td>S2 Start<\/td><td>đang nhấn<\/td><\/tr><tr><td>Cuộn KM1<\/td><td class=\"ok\">hút<\/td><\/tr><tr><td>Động cơ M1<\/td><td class=\"ok\">quay<\/td><\/tr><tr><td>Đèn chạy H1<\/td><td>sáng<\/td><\/tr><\/tbody><\/table>", "say": "<p>Đường dòng: +24 V → F0 → F1 95-96 → S0 → S1 → S2 → KM1 A1-A2 → 0 V. KM1 hút: tiếp điểm chính đóng (M1 quay), tiếp điểm phụ 13-14 đóng, tiếp điểm 43-44 bật đèn H1.<\/p>"}, {"t": "Nhả S2: tự giữ", "html": "<div class=\"mt-flow\"><div class=\"mt-box\"><b>+24 V<\/b><small>nguồn điều khiển<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>F0<\/b><small>cầu chì<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>F1 95-96<\/b><small>NC của relay nhiệt<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>S0<\/b><small>dừng khẩn, NC<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>S1<\/b><small>Stop, NC<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>S2 ∥ KM1 13-14<\/b><small>Start NO ∥ tự giữ<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>KM1 A1-A2<\/b><small>cuộn hút<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>0 V<\/b><\/div><\/div><table class=\"mt-tab\"><thead><tr><th scope=\"col\">Thiết bị<\/th><th scope=\"col\">Trạng thái<\/th><\/tr><\/thead><tbody><tr><td>S2 Start<\/td><td>nhả<\/td><\/tr><tr><td>Cuộn KM1<\/td><td class=\"ok\">hút<\/td><\/tr><tr><td>Động cơ M1<\/td><td class=\"ok\">quay<\/td><\/tr><tr><td>Đèn chạy H1<\/td><td>sáng<\/td><\/tr><\/tbody><\/table>", "ask": {"q": "Nhả nút S2. Cuộn KM1 còn hút không?", "o": ["Còn: dòng đi qua tiếp điểm KM1 13-14 song song với S2", "Không: KM1 nhả ngay khi nhả S2", "Chỉ còn hút nếu giữ S1"], "a": 0}, "say": "<p>Tiếp điểm 13-14 của chính KM1 thay S2 giữ đường dòng: mạch <b>tự giữ<\/b>. Mạch này học kỹ ở Chương 5.<\/p>"}, {"t": "Nhấn S1: KM1 nhả, M1 dừng", "html": "<div class=\"mt-flow\"><div class=\"mt-box\"><b>+24 V<\/b><small>nguồn điều khiển<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>F0<\/b><small>cầu chì<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>F1 95-96<\/b><small>NC của relay nhiệt<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>S0<\/b><small>dừng khẩn, NC<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box warn\"><b>S1<\/b><small>Stop, NC<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>S2 ∥ KM1 13-14<\/b><small>Start NO ∥ tự giữ<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box dim\"><b>KM1 A1-A2<\/b><small>cuộn hút<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>0 V<\/b><\/div><\/div><table class=\"mt-tab\"><thead><tr><th scope=\"col\">Thiết bị<\/th><th scope=\"col\">Trạng thái<\/th><\/tr><\/thead><tbody><tr><td>S2 Start<\/td><td>nhả<\/td><\/tr><tr><td>Cuộn KM1<\/td><td class=\"dim\">nhả<\/td><\/tr><tr><td>Động cơ M1<\/td><td class=\"dim\">đứng yên<\/td><\/tr><tr><td>Đèn chạy H1<\/td><td>tắt<\/td><\/tr><\/tbody><\/table>", "say": "<p>S1 thường đóng bị mở ra, cắt đường dòng. KM1 nhả, 13-14 mở lại; nhả S1 thì máy vẫn đứng yên cho tới lần nhấn Start sau.<\/p>"}]}, {"label": "Ví dụ: Ba tầng phân phối nhà xưởng", "note": "Mỗi tầng có bảo vệ riêng; chọn lọc giữ cho phần không lỗi vẫn có điện.", "steps": [{"t": "Xưởng chạy bình thường", "html": "<div class=\"mt-flow\"><div class=\"mt-box\"><b>MSB<\/b><small>tủ phân phối chính<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>DB1<\/b><small>tủ khu vực<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>Tủ máy 1<\/b><small>Q1 · KM1 · F1<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>Tủ máy 2<\/b><small>Q1 · KM1 · F1<\/small><\/div><\/div><table class=\"mt-tab\"><thead><tr><th scope=\"col\">Tầng · thiết bị bảo vệ<\/th><th scope=\"col\">Trạng thái<\/th><th scope=\"col\">Cấp điện cho<\/th><\/tr><\/thead><tbody><tr><td>MSB · CB tổng<\/td><td class=\"ok\">đóng<\/td><td>toàn xưởng<\/td><\/tr><tr><td>DB1 · CB nhánh khu A<\/td><td class=\"ok\">đóng<\/td><td>máy 1, máy 2<\/td><\/tr><tr><td>Tủ máy 1 · Q1<\/td><td class=\"ok\">đóng<\/td><td>băng tải 1<\/td><\/tr><tr><td>Tủ máy 2 · Q1<\/td><td class=\"ok\">đóng<\/td><td>băng tải 2<\/td><\/tr><\/tbody><\/table><p class=\"mt-cap\">Sơ đồ giả định: MSB → DB1 → tủ máy 1, tủ máy 2.<\/p>", "say": "<p>Mỗi tầng có thiết bị bảo vệ của mình. Máy là tầng cuối, gần tải nhất.<\/p>"}, {"t": "Ngắn mạch ở cáp động cơ máy 2", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Tầng · thiết bị bảo vệ<\/th><th scope=\"col\">Trạng thái<\/th><th scope=\"col\">Cấp điện cho<\/th><\/tr><\/thead><tbody><tr><td>MSB · CB tổng<\/td><td class=\"ok\">đóng<\/td><td>toàn xưởng<\/td><\/tr><tr><td>DB1 · CB nhánh khu A<\/td><td class=\"ok\">đóng<\/td><td>máy 1, máy 2<\/td><\/tr><tr><td>Tủ máy 1 · Q1<\/td><td class=\"ok\">đóng<\/td><td>băng tải 1<\/td><\/tr><tr><td>Tủ máy 2 · Q1<\/td><td class=\"ok\">đóng<\/td><td class=\"hi\">băng tải 2 · ngắn mạch<\/td><\/tr><\/tbody><\/table><p class=\"mt-cap\">Sơ đồ giả định: MSB → DB1 → tủ máy 1, tủ máy 2.<\/p>", "ask": {"q": "Thiết bị nào nên cắt?", "o": ["CB tổng ở MSB", "Q1 của tủ máy 2, gần sự cố nhất", "Mọi CB từ MSB tới tủ máy 2"], "a": 1}, "say": "<p>Dòng sự cố đi qua cả ba tầng: MSB, DB1 và Q1 của tủ máy 2 đều “thấy” nó.<\/p>"}, {"t": "Có chọn lọc: chỉ máy 2 dừng", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Tầng · thiết bị bảo vệ<\/th><th scope=\"col\">Trạng thái<\/th><th scope=\"col\">Cấp điện cho<\/th><\/tr><\/thead><tbody><tr><td>MSB · CB tổng<\/td><td class=\"ok\">đóng<\/td><td>toàn xưởng<\/td><\/tr><tr><td>DB1 · CB nhánh khu A<\/td><td class=\"ok\">đóng<\/td><td>máy 1, máy 2<\/td><\/tr><tr><td>Tủ máy 1 · Q1<\/td><td class=\"ok\">đóng<\/td><td>băng tải 1<\/td><\/tr><tr><td>Tủ máy 2 · Q1<\/td><td class=\"bad\">cắt<\/td><td class=\"hi\">băng tải 2 · ngắn mạch<\/td><\/tr><\/tbody><\/table><p class=\"mt-cap\">Sơ đồ giả định: MSB → DB1 → tủ máy 1, tủ máy 2.<\/p>", "say": "<p>Q1 của tủ máy 2 cắt, máy 1 và cả xưởng vẫn chạy. Đó là <b>chọn lọc<\/b>: thiết bị gần sự cố nhất cắt trước.<\/p>"}, {"t": "Bẫy: không chọn lọc, máy 1 cũng dừng", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Tầng · thiết bị bảo vệ<\/th><th scope=\"col\">Trạng thái<\/th><th scope=\"col\">Cấp điện cho<\/th><\/tr><\/thead><tbody><tr><td>MSB · CB tổng<\/td><td class=\"ok\">đóng<\/td><td>toàn xưởng<\/td><\/tr><tr><td>DB1 · CB nhánh khu A<\/td><td class=\"bad\">cắt<\/td><td>máy 1, máy 2<\/td><\/tr><tr><td>Tủ máy 1 · Q1<\/td><td class=\"bad\">mất nguồn<\/td><td>băng tải 1<\/td><\/tr><tr><td>Tủ máy 2 · Q1<\/td><td class=\"bad\">mất nguồn<\/td><td class=\"hi\">băng tải 2 · ngắn mạch<\/td><\/tr><\/tbody><\/table><p class=\"mt-cap\">Sơ đồ giả định: MSB → DB1 → tủ máy 1, tủ máy 2.<\/p>", "say": "<p>Nếu CB của DB1 cắt trước, máy 1 không có lỗi vẫn mất điện. Chọn lọc chỉ được khẳng định bằng bảng hoặc đường đặc tính của nhà sản xuất (Chương 3, 8, 9), không đoán theo dòng định mức.<\/p>"}]}, {"label": "Bẫy: Contactor không cắt được ngắn mạch", "note": "Ngắn mạch phải do CB hoặc cầu chì cắt; contactor và relay nhiệt không làm việc này.", "steps": [{"t": "Băng tải đang chạy", "html": "<div class=\"mt-flow\"><div class=\"mt-box\"><b>L1 L2 L3<\/b><small>nguồn 3 pha<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>Q1<\/b><small>CB động lực<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>KM1<\/b><small>tiếp điểm chính<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>F1<\/b><small>phần tử nhiệt<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>M1<\/b><small>động cơ<\/small><\/div><\/div>"}, {"t": "Cáp động cơ bị chạm giữa hai pha", "html": "<div class=\"mt-flow\"><div class=\"mt-box\"><b>L1 L2 L3<\/b><small>nguồn 3 pha<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>Q1<\/b><small>CB động lực<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>KM1<\/b><small>tiếp điểm chính<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>F1<\/b><small>phần tử nhiệt<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box warn\"><b>M1<\/b><small>động cơ<\/small><\/div><\/div><p class=\"mt-calc\">Ngắn mạch: dòng tăng lên rất lớn so với dòng làm việc, chỉ bị giới hạn bởi nguồn và dây dẫn.<\/p>", "ask": {"q": "Ngay lúc ngắn mạch, thiết bị nào phải cắt dòng sự cố?", "o": ["KM1, vì nó đang đóng mạch động lực", "F1, relay nhiệt", "Q1, thiết bị bảo vệ ngắn mạch"], "a": 2}}, {"t": "KM1 không biết có ngắn mạch", "html": "<div class=\"mt-flow\"><div class=\"mt-box\"><b>L1 L2 L3<\/b><small>nguồn 3 pha<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>Q1<\/b><small>CB động lực<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>KM1<\/b><small>tiếp điểm chính<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>F1<\/b><small>phần tử nhiệt<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box warn\"><b>M1<\/b><small>động cơ<\/small><\/div><\/div><table class=\"mt-tab\"><thead><tr><th scope=\"col\">Thiết bị<\/th><th scope=\"col\">Vì sao không làm việc này<\/th><\/tr><\/thead><tbody><tr><td>KM1<\/td><td>chỉ đóng cắt theo lệnh của cuộn hút; không được chế tạo để cắt dòng ngắn mạch<\/td><\/tr><tr><td>F1<\/td><td>tác động theo nhiệt, quá chậm với ngắn mạch; không thay bảo vệ ngắn mạch<\/td><\/tr><\/tbody><\/table>", "say": "<p>Cuộn hút KM1 vẫn có điện, nên KM1 vẫn đóng. Relay nhiệt F1 cần thời gian để nóng lên.<\/p>"}, {"t": "Q1 tác động, cắt cả ba pha", "html": "<div class=\"mt-flow\"><div class=\"mt-box\"><b>L1 L2 L3<\/b><small>nguồn 3 pha<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box warn\"><b>Q1<\/b><small>CB động lực<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box dim\"><b>KM1<\/b><small>tiếp điểm chính<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box dim\"><b>F1<\/b><small>phần tử nhiệt<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box dim\"><b>M1<\/b><small>động cơ<\/small><\/div><\/div>", "say": "<p>Bảo vệ ngắn mạch là việc của CB hoặc cầu chì phía trước. Contactor và relay nhiệt có thể còn bị hỏng do dòng ngắn mạch; mức hư hỏng được phép phụ thuộc kiểu phối hợp do nhà sản xuất xác nhận (Chương 6).<\/p>"}]}, {"label": "Lỗi: Nhấn Stop rồi tháo dây động cơ", "note": "Stop dừng máy nhưng không cô lập nguồn; phía trên KM1 vẫn có điện.", "steps": [{"t": "Máy đang chạy, cần thay dây động cơ", "html": "<div class=\"mt-flow\"><div class=\"mt-box\"><b>L1 L2 L3<\/b><small>nguồn 3 pha<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>Q1<\/b><small>CB động lực<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>KM1<\/b><small>tiếp điểm chính<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>F1<\/b><small>phần tử nhiệt<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>M1<\/b><small>động cơ<\/small><\/div><\/div>"}, {"t": "Nhấn Stop S1: M1 dừng", "html": "<div class=\"mt-flow\"><div class=\"mt-box\"><b>L1 L2 L3<\/b><small>nguồn 3 pha<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>Q1<\/b><small>CB động lực<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box dim\"><b>KM1<\/b><small>tiếp điểm chính<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box dim\"><b>F1<\/b><small>phần tử nhiệt<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box dim\"><b>M1<\/b><small>động cơ<\/small><\/div><\/div><table class=\"mt-tab\"><thead><tr><th scope=\"col\">Vị trí<\/th><th scope=\"col\">Còn điện?<\/th><\/tr><\/thead><tbody><tr><td>Đầu vào KM1 (phía Q1)<\/td><td class=\"bad\">CÒN, 3 pha<\/td><\/tr><tr><td>Mạch điều khiển 24 V<\/td><td class=\"bad\">CÒN<\/td><\/tr><tr><td>Đầu ra KM1 tới M1<\/td><td>không, khi KM1 đang nhả<\/td><\/tr><\/tbody><\/table>", "ask": {"q": "Đã nhấn Stop và động cơ đã dừng. Tháo dây động cơ được chưa?", "o": ["Được, vì động cơ đã đứng yên", "Chưa: phải cô lập, khóa, treo thẻ và xác nhận không còn điện", "Được, nếu đèn chạy H1 đã tắt"], "a": 1}}, {"t": "Vì sao chưa an toàn", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Chuyện có thể xảy ra<\/th><th scope=\"col\">Hậu quả<\/th><\/tr><\/thead><tbody><tr><td>Người khác nhấn Start, hoặc PLC ra lệnh<\/td><td class=\"bad\">KM1 hút, M1 có điện lại<\/td><\/tr><tr><td>Tiếp điểm chính KM1 bị dính, lõi bị kẹt<\/td><td class=\"bad\">M1 vẫn có điện dù cuộn đã nhả<\/td><\/tr><tr><td>Phía trên KM1 luôn có điện<\/td><td class=\"bad\">chạm vào là bị điện giật<\/td><\/tr><\/tbody><\/table>", "say": "<p>Stop và dừng khẩn là lệnh <b>dừng máy<\/b>, không phải <b>cô lập nguồn<\/b>. Đèn tắt không chứng minh là hết điện.<\/p>"}, {"t": "Sửa: cô lập, khóa, xác nhận", "html": "<div class=\"mt-flow\"><div class=\"mt-box done\"><b>Cắt thiết bị cách ly<\/b><small>đúng thiết bị, đúng nhánh<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box done\"><b>Khóa, treo thẻ<\/b><small>LOTO<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box done\"><b>Xác nhận không còn điện<\/b><small>người có năng lực, dụng cụ phù hợp<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box on\"><b>Mới làm việc<\/b><\/div><\/div>", "say": "<p>Quy trình đầy đủ ở Bài 7. Học viên chỉ làm theo quy trình của nơi làm việc và khi được giao việc.<\/p>"}]}, {"label": "Bẫy: Tăng dòng chỉnh relay nhiệt cho hết dừng", "note": "Bảo vệ tác động là triệu chứng; tăng dòng chỉnh làm mất bảo vệ động cơ.", "steps": [{"t": "Băng tải hay dừng, đèn H2 sáng", "html": "<div class=\"mt-flow\"><div class=\"mt-box\"><b>+24 V<\/b><small>nguồn điều khiển<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>F0<\/b><small>cầu chì<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box warn\"><b>F1 95-96<\/b><small>NC của relay nhiệt<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>S0<\/b><small>dừng khẩn, NC<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>S1<\/b><small>Stop, NC<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>S2 ∥ KM1 13-14<\/b><small>Start NO ∥ tự giữ<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box dim\"><b>KM1 A1-A2<\/b><small>cuộn hút<\/small><\/div><span class=\"mt-arr\" aria-hidden=\"true\">→<\/span><div class=\"mt-box\"><b>0 V<\/b><\/div><\/div><table class=\"mt-tab\"><thead><tr><th scope=\"col\">Dấu hiệu<\/th><th scope=\"col\">Ý nghĩa<\/th><\/tr><\/thead><tbody><tr><td>H2 sáng (F1 97-98 đóng)<\/td><td>relay nhiệt F1 đã tác động<\/td><\/tr><tr><td>KM1 nhả<\/td><td>vì F1 95-96 đã mở<\/td><\/tr><\/tbody><\/table>"}, {"t": "Định vặn tăng dòng chỉnh của F1", "html": "<p class=\"mt-calc\">“Cứ vặn F1 lên cao là máy hết dừng”<\/p>", "ask": {"q": "Nên làm gì trước?", "o": ["Vặn dòng chỉnh lên mức lớn nhất", "Nối tắt tiếp điểm 95-96", "Tìm nguyên nhân quá tải và so dòng chỉnh với nhãn động cơ"], "a": 2}}, {"t": "Hậu quả nếu vặn tăng", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Việc làm<\/th><th scope=\"col\">Hậu quả<\/th><\/tr><\/thead><tbody><tr><td>Dòng chỉnh cao hơn dòng định mức động cơ<\/td><td class=\"bad\">F1 không còn bảo vệ được M1<\/td><\/tr><tr><td>Quá tải vẫn còn<\/td><td class=\"bad\">cuộn dây động cơ quá nhiệt, cách điện xuống cấp, có thể cháy<\/td><\/tr><\/tbody><\/table>"}, {"t": "Sửa: tìm nguyên nhân gốc", "html": "<table class=\"mt-tab\"><thead><tr><th scope=\"col\">Kiểm tra<\/th><th scope=\"col\">Ví dụ nguyên nhân<\/th><\/tr><\/thead><tbody><tr><td>Cơ khí (khi đã cô lập, khóa nguồn)<\/td><td>băng tải kẹt, ổ bi hỏng, tải nặng hơn thiết kế<\/td><\/tr><tr><td>Điện (đo điện áp chỉ do người có năng lực, được giao việc, theo quy trình)<\/td><td>mất một pha, điện áp thấp<\/td><\/tr><tr><td>Cài đặt<\/td><td>dòng chỉnh không khớp nhãn động cơ, hướng dẫn hãng<\/td><\/tr><\/tbody><\/table>", "say": "<p>Bảo vệ tác động là <b>triệu chứng<\/b>. Cách chỉnh relay nhiệt và chẩn đoán học ở Chương 6 và Chương 10.<\/p>"}]}]});
makeMtEx(document.getElementById("ex-l1"),"l1",[{"kind": "pick", "t": "Xếp khí cụ vào nhóm chức năng", "d": "<p>Chọn nhóm chức năng <b>chính<\/b> của mỗi thiết bị trong máy băng tải của bài.<\/p>", "cats": ["Cách ly", "Đóng cắt", "Bảo vệ", "Điều khiển", "Thao tác – báo hiệu"], "items": [{"q": "Relay nhiệt F1", "a": 2}, {"q": "Nút Start S2", "a": 4}, {"q": "Tiếp điểm chính của KM1", "a": 1}, {"q": "Cầu chì F0 của mạch 24 V", "a": 2}, {"q": "Cầu dao cách ly có khóa ở cửa tủ, dùng khi bảo trì", "a": 0}, {"q": "Relay thời gian trễ 5 s trước khi bật còi", "a": 3}, {"q": "Đèn báo quá tải H2", "a": 4}, {"q": "Relay trung gian nhận lệnh của PLC để cấp điện cho cuộn KM1", "a": 3}], "hints": ["Hỏi “nó tự tác động khi có sự cố không?”: có thì là bảo vệ.", "Thiết bị người vận hành chạm vào hoặc nhìn thấy là thao tác – báo hiệu; thiết bị xử lý tín hiệu nhỏ là điều khiển.", "Tiếp điểm chính của contactor đóng cắt dòng động cơ; cầu dao có khóa dùng khi bảo trì là cách ly."], "why": "F1 và F0 tự tác động khi có sự cố: bảo vệ. S2 và H2 là chỗ người ra lệnh và nhận tin: thao tác – báo hiệu. Tiếp điểm chính KM1 đóng cắt dòng động cơ. Timer và relay trung gian xử lý tín hiệu: điều khiển. Cầu dao có khóa để tách máy khỏi nguồn khi bảo trì: cách ly."}, {"kind": "order", "t": "Đường năng lượng từ xưởng tới động cơ", "d": "<p>Sắp xếp theo đúng thứ tự năng lượng đi qua, từ phía nguồn (trên cùng) tới động cơ (dưới cùng). Dùng nút ↑ ↓.<\/p>", "items": ["Máy biến áp hạ áp của xưởng", "Tủ phân phối chính MSB", "Tủ phân phối khu vực DB1", "Q1: CB động lực trong tủ máy", "Tiếp điểm chính KM1", "Phần tử nhiệt của relay F1", "Động cơ M1"], "hints": ["Bắt đầu từ nơi điện vào xưởng, kết thúc ở tải.", "Tủ lớn ở trên, tủ của máy ở dưới; trong tủ máy, CB đứng trước contactor.", "Trong mạch khởi động trực tiếp của bài: Q1 → KM1 → F1 → M1."], "why": "Năng lượng đi từ máy biến áp qua MSB, DB1 tới tủ máy; trong tủ máy qua Q1 (bảo vệ ngắn mạch), tiếp điểm chính KM1 (đóng cắt theo lệnh), phần tử nhiệt F1 (đo dòng để bảo vệ quá tải) rồi tới động cơ M1."}, {"kind": "pick", "t": "Sự cố nào, khí cụ nào", "d": "<p>Mỗi tình huống cần một nhóm khí cụ làm việc. Chọn nhóm <b>phải<\/b> làm việc đó. Các tình huống chỉ để phân tích, không phải hướng dẫn làm trên tủ thật.<\/p>", "cats": ["Bảo vệ ngắn mạch (CB, cầu chì)", "Bảo vệ quá tải động cơ (relay nhiệt)", "Đóng cắt theo lệnh (contactor)", "Cách ly, khóa nguồn"], "items": [{"q": "Cáp động cơ bị chạm giữa hai pha", "a": 0}, {"q": "Băng tải bị quá tải kéo dài, động cơ nóng dần", "a": 1}, {"q": "PLC bật, tắt động cơ hàng trăm lần mỗi ca", "a": 2}, {"q": "Giữ cho máy không thể có điện trong lúc thay ổ bi động cơ", "a": 3}, {"q": "Dây trong mạch điều khiển 24 V bị chập xuống 0 V", "a": 0}, {"q": "Người vận hành nhấn Stop để dừng băng tải cuối ca", "a": 2}], "hints": ["Ngắn mạch cần cắt rất nhanh: không phải việc của relay nhiệt hay contactor.", "Quá tải kéo dài làm nóng dần: relay nhiệt đo dòng và tác động theo thời gian.", "Stop và lệnh PLC chỉ dừng máy qua contactor; khi sửa máy phải cô lập và khóa nguồn."], "why": "Chập pha – pha và chập dây 24 V là ngắn mạch: CB hoặc cầu chì phía trước phải cắt. Quá tải kéo dài là việc của relay nhiệt. Bật tắt theo lệnh (PLC, nút Stop) là việc của contactor. Thay ổ bi cần cách ly và khóa nguồn, vì Stop không ngăn được máy có điện trở lại."}]);
